label("$B$", B, NE);
label("$C$", C, dir(90));
label("$D$", D, S);
label("$E$", E, SW);
label("$F$", F, SE);
label("$M$", M, SW);
label("$N$", N, SE);
label("$P$", P, SE);
label("$Q$", Q, W);
label("$R$", R, S);
